shader=>{
        before.call(original,shader);shader.uniforms.arenaSides=sides;
        shader.vertexShader=(baked?'attribute vec3 warehouseAnchor;\n':'')+'varying vec3 vArenaWorld;varying vec3 vArenaAnchor;\n'+shader.vertexShader;
        shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>',`#include <project_vertex>
          vec4 arenaP=vec4(transformed,1.0),arenaAnchor=vec4(${baked?'warehouseAnchor':'0.0,0.0,0.0'},1.0);
          #ifdef USE_INSTANCING
          arenaP=instanceMatrix*arenaP;
          arenaAnchor=instanceMatrix*arenaAnchor;
          #endif
          vArenaWorld=(modelMatrix*arenaP).xyz;
          vArenaAnchor=(modelMatrix*arenaAnchor).xyz;`);
        shader.fragmentShader='varying vec3 vArenaWorld;varying vec3 vArenaAnchor;uniform vec4 arenaSides;\n'+shader.fragmentShader;
        shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>',`#include <clipping_planes_fragment>
          if(vArenaWorld.y>.85 && vArenaWorld.x>260. && vArenaWorld.x<327. && vArenaWorld.z>145. && vArenaWorld.z<230.){
            if((arenaSides.x>.5 && vArenaAnchor.x>299.5) || (arenaSides.y>.5 && vArenaAnchor.z>210.5) ||
               (arenaSides.z>.5 && vArenaAnchor.z<156.5) || (arenaSides.w>.5 && vArenaAnchor.x<267.5))discard;
          }`);
      }

